                            initialContentExit = androidx.compose.animation.ExitTransition.None
                        )
                    } else if (targetState.depth > initialState.depth) {
                        androidx.compose.animation.ContentTransform(
                            targetContentEnter = androidx.compose.animation.slideInHorizontally(
                                animationSpec = androidx.compose.animation.core.tween(300),
                                initialOffsetX = { width -> width }
                            ) + androidx.compose.animation.fadeIn(animationSpec = androidx.compose.animation.core.tween(250)),
                            initialContentExit = androidx.compose.animation.slideOutHorizontally(
                                animationSpec = androidx.compose.animation.core.tween(300),
                                targetOffsetX = { width -> -width / 3 }
                            ) + androidx.compose.animation.fadeOut(animationSpec = androidx.compose.animation.core.tween(250)),
                            targetContentZIndex = 1f
                        )
                    } else {
                        androidx.compose.animation.ContentTransform(
                            targetContentEnter = androidx.compose.animation.slideInHorizontally(
                                animationSpec = androidx.compose.animation.core.tween(300),
                                initialOffsetX = { width -> -width / 3 }
                            ) + androidx.compose.animation.fadeIn(animationSpec = androidx.compose.animation.core.tween(250)),
                            initialContentExit = androidx.compose.animation.slideOutHorizontally(
                                animationSpec = androidx.compose.animation.core.tween(300),
                                targetOffsetX = { width -> width }
                            ) + androidx.compose.animation.fadeOut(animationSpec = androidx.compose.animation.core.tween(250)),
                            targetContentZIndex = -1f
                        )
                    }
                },
                label = "NavStack"
            ) { state ->
                val currentPage = if (state.depth == navState.depth && state.path == navState.path) {
                    windowPages.lastOrNull() ?: state.page
                } else {
                    windowPages.getOrNull(state.depth - 1) ?: state.page
                }
                currentPage?.let {
                    DynamicNodeView(it, dispatch, androidx.compose.ui.Modifier.fillMaxSize())
                }
            }
    
            androidx.compose.animation.AnimatedVisibility(
                visible = formShown.value,
                enter = androidx.compose.animation.slideInVertically(
                    animationSpec = androidx.compose.animation.core.tween(350, easing = androidx.compose.animation.core.FastOutSlowInEasing),
                    initialOffsetY = { fullHeight -> fullHeight }
                ) + androidx.compose.animation.fadeIn(animationSpec = androidx.compose.animation.core.tween(250)),
                exit = androidx.compose.animation.slideOutVertically(
                    animationSpec = androidx.compose.animation.core.tween(300, easing = androidx.compose.animation.core.FastOutLinearInEasing),
                    targetOffsetY = { fullHeight -> fullHeight }
                ) + androidx.compose.animation.fadeOut(animationSpec = androidx.compose.animation.core.tween(200))
            ) {
                androidx.compose.material3.Surface(
                    modifier = androidx.compose.ui.Modifier.fillMaxSize(),
                    color = androidx.compose.material3.MaterialTheme.colorScheme.background
                ) {
                    lastForm.value?.let {
                        DynamicNodeView(it, dispatch, androidx.compose.ui.Modifier.fillMaxSize())
                    }
                }
            }
    
            if (sheetShown.value && lastSheet.value != null) {
                androidx.compose.material3.ModalBottomSheet(
                    sheetState = sheetState,
                    onDismissRequest = {
                        sheetShown.value = false
                        if (hasOverlay && onDismiss.isNotEmpty()) {
                            dispatch(onDismiss, null)
                        }
                    }
                ) {
                    DynamicNodeView(lastSheet.value!!, dispatch, androidx.compose.ui.Modifier.fillMaxWidth())
                }
            }
        }
}


"page" -> {
    val title = node.getString("title", "")
        val subtitle = node.getString("subtitle", "")
        val largeTitle = node.getBoolean("large_title", false)
        val topStyle = node.getString("top_style", "soft")
        val onBackStr = node.getString("on_back", "")
        val presentation = node.getString("presentation", "push")
        val isSheet = presentation == "sheet"
        val isForm = presentation == "form" || presentation == "dialog" || presentation == "modal" || presentation == "fullscreen"
    
        val toolbarNode = node.children.firstOrNull { it.name == "toolbartop" }
        val toolbarItems = toolbarNode?.children ?: emptyList()
        val leadingItems = toolbarItems.filter {
            (it.getString("placement", "").ifEmpty { it.children.firstOrNull()?.getString("placement", "") ?: "trailing" }) == "leading"
        }
        val trailingItems = toolbarItems.filter {
            (it.getString("placement", "").ifEmpty { it.children.firstOrNull()?.getString("placement", "") ?: "trailing" }) != "leading"
        }
        val bodyChildren = node.children.filter { it.name != "toolbartop" && it.name != "toolbarbottom" }
        val sectionSpacing = node.getInt("section_spacing", 16)
    
        if (isSheet) {
            androidx.compose.foundation.layout.Column(
                modifier = androidx.compose.ui.Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 24.dp)
                    .padding(bottom = 32.dp),
                verticalArrangement = androidx.compose.foundation.layout.Arrangement.spacedBy(sectionSpacing.dp)
            ) {
                bodyChildren.forEach { child ->
                    DynamicNodeView(child, dispatch, androidx.compose.ui.Modifier.fillMaxWidth())
                }
            }
        } else {
            val titleBlock: @androidx.compose.runtime.Composable () -> Unit = {
                androidx.compose.foundation.layout.Column {
                    androidx.compose.material3.Text(title)
                    if (subtitle.isNotEmpty()) {
                        androidx.compose.material3.Text(subtitle, style = androidx.compose.material3.MaterialTheme.typography.bodySmall)
                    }
                }
            }
    
            val navIconBlock: @androidx.compose.runtime.Composable () -> Unit = {
                if (leadingItems.isNotEmpty()) {
                    androidx.compose.foundation.layout.Row(verticalAlignment = Alignment.CenterVertically) {
                        leadingItems.forEach { item -> DynamicNodeView(item, dispatch) }
                    }
                } else if (onBackStr.isNotEmpty()) {
                    androidx.compose.material3.IconButton(onClick = { dispatch(onBackStr, null) }) {
                        androidx.compose.material3.Icon(
                            imageVector = if (isForm) AppCloseIcon else AppBackIcon,
                            contentDescription = if (isForm) "Close" else "Back",
                            modifier = androidx.compose.ui.Modifier.size(24.dp)
                        )
                    }
                }
            }
    
            val actionsBlock: @androidx.compose.runtime.Composable androidx.compose.foundation.layout.RowScope.() -> Unit = {
                trailingItems.forEach { item -> DynamicNodeView(item, dispatch) }
            }
    
            val isLarge = largeTitle && topStyle != "hard"
            val scrollBehavior = if (isLarge) {
                androidx.compose.material3.TopAppBarDefaults.exitUntilCollapsedScrollBehavior()
            } else {
                androidx.compose.material3.TopAppBarDefaults.pinnedScrollBehavior()
            }
            androidx.compose.material3.Scaffold(
                modifier = Modifier.nestedScroll(scrollBehavior.nestedScrollConnection),
                topBar = {
                    if (isLarge) {
                        androidx.compose.material3.LargeTopAppBar(
                            title = titleBlock,
                            navigationIcon = navIconBlock,
                            actions = actionsBlock,
                            scrollBehavior = scrollBehavior
                        )
                    } else {
                        androidx.compose.material3.TopAppBar(
                            title = titleBlock,
                            navigationIcon = navIconBlock,
                            actions = actionsBlock,
                            scrollBehavior = scrollBehavior
                        )
                    }
                }
            ) { innerPadding ->
                androidx.compose.foundation.layout.Box(
                    modifier = androidx.compose.ui.Modifier
                        .fillMaxSize()
                        .verticalScroll(androidx.compose.foundation.rememberScrollState())
                        .padding(innerPadding)
                ) {
                    androidx.compose.foundation.layout.Column(
                        modifier = androidx.compose.ui.Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp, vertical = 8.dp),
                        verticalArrangement = androidx.compose.foundation.layout.Arrangement.spacedBy(sectionSpacing.dp)
                    ) {
                        bodyChildren.forEach { child ->
                            DynamicNodeView(child, dispatch, androidx.compose.ui.Modifier.fillMaxWidth())
                        }
                    }
                }
            }
        }
}


"textinput" -> {
    val externalValue = node.getString("value", "")
        val placeholder = node.getString("placeholder", "")
        val onChangeStr = node.getString("on_change", "")
        var localText by androidx.compose.runtime.remember { androidx.compose.runtime.mutableStateOf(externalValue) }
        var lastSent by androidx.compose.runtime.remember { androidx.compose.runtime.mutableStateOf(externalValue) }
        var isFocused by androidx.compose.runtime.remember { androidx.compose.runtime.mutableStateOf(false) }
    
        androidx.compose.runtime.LaunchedEffect(externalValue, isFocused) {
            if (!isFocused && externalValue != localText) {
                localText = externalValue
                lastSent = externalValue
            }
        }
    
        OutlinedTextField(
            value = localText,
            onValueChange = { newText ->
                localText = newText
                if (onChangeStr.isNotEmpty() && newText != lastSent) {
                    lastSent = newText
                    dispatch(onChangeStr, org.json.JSONObject().put("value", newText))
                }
            },
            placeholder = { Text(placeholder) },
            singleLine = true,
            shape = androidx.compose.foundation.shape.RoundedCornerShape(10.dp),
            modifier = modifier
                .fillMaxWidth()
                .onFocusChanged { isFocused = it.isFocused }
        )
}


"image" -> {
    val src = node.getString("src", "")
        val size = node.getInt("size", 0)
        val w = node.getInt("width", size)
        val h = node.getInt("height", if (size > 0) size else 180)
        val radius = node.getInt("corner_radius", 0)
        val mode = node.getString("content_mode", "cover")
        val opacity = node.getInt("opacity", 100).toFloat() / 100f
        DynamicNetworkOrAssetImage(
            src = src,
            widthDp = w,
            heightDp = h,
            cornerRadiusDp = radius,
            isContain = (mode == "contain" || mode == "fit"),
            opacity = opacity,
            modifier = modifier
        )
}


"toolbartop" -> {
    node.children.forEach { DynamicNodeView(it, dispatch) }
}


"section" -> {
    val hdrNode = node.children.firstOrNull { it.name == "section_header" }?.children?.firstOrNull()
        val ftrNode = node.children.firstOrNull { it.name == "section_footer" }?.children?.firstOrNull()
        val bodyChildren = node.children.filter { it.name != "section_header" && it.name != "section_footer" }
        val count = bodyChildren.size
        Column(modifier = modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(6.dp)) {
            if (hdrNode != null) {
                Box(modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp)) {
                    DynamicNodeView(hdrNode, dispatch, Modifier.fillMaxWidth())
                }
            }
            Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                for (i in 0 until count) {
                    val child = bodyChildren[i]
                    val shape = when {
                        count == 1 -> androidx.compose.foundation.shape.RoundedCornerShape(16.dp)
                        i == 0 -> androidx.compose.foundation.shape.RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp, bottomStart = 4.dp, bottomEnd = 4.dp)
                        i == count - 1 -> androidx.compose.foundation.shape.RoundedCornerShape(topStart = 4.dp, topEnd = 4.dp, bottomStart = 16.dp, bottomEnd = 16.dp)
                        else -> androidx.compose.foundation.shape.RoundedCornerShape(4.dp)
                    }
                    val isBtn = child.name == "button"
                    val isPicker = child.getBoolean("is_picker", false)
                    val actStr = child.getString("action", "")
                    val rowBgName = child.getString("background", "")
                    val rowBgColor = resolveAppColor(rowBgName)
                    val rowBgGrad = child.props["background_gradient"] as? org.json.JSONObject
                    val rowBrush = if (rowBgGrad != null) resolveAppGradientBrush(rowBgGrad) else null
                    val hasRowBg = rowBgColor != null || rowBrush != null
                    val cleanChild = if (hasRowBg) {
                        DynamicUINode(
                            child.name,
                            child.props.filterKeys { it != "background" && it != "background_gradient" },
                            child.children,
                            child.inList
                        )
                    } else {
                        child
                    }
                    Surface(
                        shape = shape,
                        color = if (rowBrush != null) Color.Transparent else (rowBgColor ?: MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.55f)),
                        modifier = Modifier.fillMaxWidth().clip(shape)
                            .let { m -> if (rowBrush != null) m.background(brush = rowBrush) else m }
                            .let { m -> if (isBtn && actStr.isNotEmpty()) m.clickable { dispatch(actStr, null) } else m }
                    ) {
                        Box(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 14.dp)) {
                            if (isPicker) {
                                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                                    Text(child.getString("picker_title", ""), style = MaterialTheme.typography.bodyLarge)
                                    Text(child.getString("picker_value", "") + "  ›", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                }
                            } else if (isBtn) {
                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                    CompositionLocalProvider(LocalContentColor provides (resolveAppColor(child.getString("color", "")) ?: MaterialTheme.colorScheme.primary)) {
                                        cleanChild.children.forEach { DynamicNodeView(it, dispatch) }
                                    }
                                }
                            } else {
                                DynamicNodeView(cleanChild, dispatch, Modifier.fillMaxWidth())
                            }
                        }
                    }
                }
            }
            if (ftrNode != null) {
                Box(modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp)) {
                    DynamicNodeView(ftrNode, dispatch, Modifier.fillMaxWidth())
                }
            }
        }
}


"grid" -> {
    val cols = maxOf(1, node.getInt("columns", 2))
        val spacing = node.getInt("spacing", 12)
        val hdrNode = node.children.firstOrNull { it.name == "section_header" }?.children?.firstOrNull()
        val ftrNode = node.children.firstOrNull { it.name == "section_footer" }?.children?.firstOrNull()
        val bodyChildren = node.children.filter { it.name != "section_header" && it.name != "section_footer" }
        val rows = bodyChildren.chunked(cols)
        Column(modifier = modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(spacing.dp)) {
            if (hdrNode != null) {
                Box(modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp)) { DynamicNodeView(hdrNode, dispatch, Modifier.fillMaxWidth()) }
            }
            rows.forEach { rowItems ->
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(spacing.dp)) {
                    for (i in 0 until cols) {
                        if (i < rowItems.size) {
                            Box(modifier = Modifier.weight(1f)) { DynamicNodeView(rowItems[i], dispatch, Modifier.fillMaxWidth()) }
                        } else {
                            Spacer(modifier = Modifier.weight(1f))
                        }
                    }
                }
            }
            if (ftrNode != null) {
                Box(modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp)) { DynamicNodeView(ftrNode, dispatch, Modifier.fillMaxWidth()) }
            }
        }
}


"spacer" -> {
    val size = node.getInt("size", 0)
        if (size > 0) {
            androidx.compose.foundation.layout.Spacer(modifier = modifier.size(size.dp))
        } else {
            androidx.compose.foundation.layout.Spacer(modifier = modifier)
        }
}

        else -> {}
    }
}
